{"implementation":"def solve(case):
    import math
    from fractions import Fraction

    def _is_int(value):
        return isinstance(value, int) and not isinstance(value, bool)

    def _importance_fraction(value, field):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise ValueError(field + " must be a finite number")
        if isinstance(value, float):
            if not math.isfinite(value):
                raise ValueError(field + " must be finite")
            return Fraction(str(value))
        return Fraction(value, 1)

    if not isinstance(case, dict):
        raise ValueError("case must be an object")

    payload = case.get("payload", case)
    if not isinstance(payload, dict):
        raise ValueError("payload must be an object")

    if "segments" not in payload or "budget" not in payload:
        raise ValueError("payload requires segments and budget")

    segments = payload["segments"]
    budget = payload["budget"]

    if not isinstance(segments, list) or not segments:
        raise ValueError("segments must be a non-empty list")
    if not _is_int(budget):
        raise ValueError("budget must be an integer")

    names = []
    importances = []
    allocations = []
    capacities = []

    for index, segment in enumerate(segments):
        if not isinstance(segment, dict):
            raise ValueError("segment must be an object")
        for key in ("name", "importance", "minimum", "capacity"):
            if key not in segment:
                raise ValueError("segment missing " + key)

        name = segment["name"]
        minimum = segment["minimum"]
        capacity = segment["capacity"]

        if not isinstance(name, str) or name == "":
            raise ValueError("segment name must be a non-empty string")
        importance = _importance_fraction(segment["importance"], "importance")
        if importance < 0:
            raise ValueError("importance must be non-negative")
        if not _is_int(minimum) or not _is_int(capacity):
            raise ValueError("minimum and capacity must be integers")
        if minimum < 0 or capacity < 0:
            raise ValueError("minimum and capacity must be non-negative")
        if minimum > capacity:
            raise ValueError("minimum cannot exceed capacity")

        names.append(name)
        importances.append(importance)
        allocations.append(minimum)
        capacities.append(capacity)

    minimum_total = sum(allocations)
    capacity_total = sum(capacities)
    if budget < minimum_total:
        raise ValueError("budget below minimum quota sum")
    if budget > capacity_total:
        raise ValueError("budget above total capacity")

    remaining = budget - minimum_total
    while remaining > 0:
        best_index = None
        best_priority = None
        for index in range(len(segments)):
            if allocations[index] >= capacities[index]:
                continue
            priority = importances[index] / Fraction(allocations[index] + 1, 1)
            if best_index is None or priority > best_priority:
                best_index = index
                best_priority = priority
        if best_index is None:
            raise ValueError("no segment has remaining capacity")
        allocations[best_index] += 1
        remaining -= 1

    primitive_allocations = []
    name_mapping = []
    for index, name in enumerate(names):
        primitive_allocations.append({
            "index": index,
            "name": name,
            "tokens": allocations[index]
        })
        name_mapping.append({
            "index": index,
            "name": name
        })

    conserved_total = sum(item["tokens"] for item in primitive_allocations)
    if conserved_total != budget:
        raise ValueError("allocation total does not match budget")

    return {
        "allocations": primitive_allocations,
        "name_mapping": name_mapping,
        "conserved_total": conserved_total
    }
"}
